insert into public.eoc_cap_items (id,section_group,section,item_no,item,iat_indicators,assess_locally,sort) values
(E'2228e3cb-989d-501a-bec2-13bb256889d7'::uuid,E'Eoc Assessment and Siting / Hazard and Vulnerability Assessment',E'Hazard and Vulnerability Assessment',1,E'The EOC can survive the effects of relevant hazards as identified in jurisdictional hazard and vulnerability assessment).','{B2.1,B2.2}'::text[],false,1),
(E'0199a261-3c10-599d-8440-156513a76865'::uuid,E'Eoc Assessment and Siting / Hazard and Vulnerability Assessment',E'Hazard and Vulnerability Assessment',2,E'The EOC Operations Manual identifies a staff position that is tasked with identifying such vulnerabilities.','{B7.1,B4.1}'::text[],false,2),
(E'f2b0085d-2371-5c61-974b-586dc20afb19'::uuid,E'Eoc Assessment and Siting / Hazard and Vulnerability Assessment',E'Hazard and Vulnerability Assessment',3,E'EOC plans and procedures specifically address the potential impacts of natural, accidental, and intentional risks to the EOC or alternate facility.','{B2.7,B7.1}'::text[],false,3),
(E'12851e3a-600b-52c4-8ea0-ed18848ca438'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',1,E'The EOC has adequate staffing based on sustained operations (i.e., minimum—72 hours, three-deep roster for each position).','{B4.2,B4.3}'::text[],false,4),
(E'5189e4a4-08b6-505c-be99-692188d780ed'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',2,E'The EOC has a system in place to manage volunteers.','{B6.4}'::text[],false,5),
(E'11b5a70e-83de-517f-ad12-9276a110a774'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',3,E'Personnel are identified to operate and maintain communications equipment at the EOC during an emergency event.','{B4.2,B7.2}'::text[],false,6),
(E'c7137076-1ed2-5f2f-8c7d-59319b709425'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',4,E'Personnel (e.g., EOC personnel, police, or other security personnel) are identified to provide security to the facility in the event of an emergency.','{B2.6}'::text[],false,7),
(E'1c033b87-2290-551d-830e-9394a04ca2e1'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',5,E'A safety or security agent is identified to issue access control badges and authorize access to EOC personnel from other jurisdictions, including Regional and National personnel.','{B2.6}'::text[],false,8),
(E'e15d92f7-7fed-5438-9107-fefa4c602c03'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',6,E'Additional government personnel are readily available to augment the EOC should the emergency escalate beyond the capability of the on-duty EOC team.','{B4.2,B6.6}'::text[],false,9),
(E'034d1a46-e1d5-58d6-bc57-8335ad4b5807'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Personnel Requirements',E'Personnel Requirements',7,E'The emergency monitoring and warning system(e.g. water level measurements) is identified and is monitored and/or staffed 24 hours, seven days a week.','{B5.6,B4.3}'::text[],false,10),
(E'874d9d08-1055-536e-b05c-6448345847ab'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',1,E'An EOC Operations and Administration/Functional Manual is developed and maintained.','{B7.1,B1.4}'::text[],false,11),
(E'1119ca8d-98ab-5c60-a373-1b509b1e5fa2'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',2,E'EOC plans and procedures identify specific communications channels to local agencies and organizations that are assigned emergency responsibilities.','{B3.4}'::text[],false,12),
(E'1c2ab834-de61-5309-82d6-eaa5ce39b7e5'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',3,E'EOC plans and procedures specifically address the potential impacts of relevant risks to the EOC or alternate facility.','{B2.7,B7.1}'::text[],false,13),
(E'cd7277fa-b7b8-555e-b5e6-ff3ebf5e63f3'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',4,E'EOC plans and procedures address the protection of computers, communications equipment, and other vital EOC equipment in a hazard event.','{B2.2,B2.7}'::text[],false,14),
(E'6166c7b9-09f9-5e09-8391-b7272fa013c6'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',5,E'Plans and procedures are in place to supplement EOC personnel, including identifying backup personnel to facilitate 24-hour operations.','{B4.2,B4.3}'::text[],false,15),
(E'eeb8806f-c571-5409-a118-435fc5ddbca0'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',6,E'Plans and procedures are in place to test the generator at full load on a regular basis.','{B2.3}'::text[],false,16),
(E'662bad00-22db-52cf-b934-dfc43335f121'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',7,E'Fuel contracts are in place to ensure regular delivery of fuel to the EOC during a long-term event.','{B2.3}'::text[],false,17),
(E'125359a8-a2e7-53f4-ac82-74ec0f75e58f'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',8,E'Resource inventories are developed and kept up-to-date.','{B6.3}'::text[],false,18),
(E'01ceefa6-7a17-54ac-820c-7eda8a26966f'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',9,E'EOC has the capability to coordinate voluntary organizations during disasters.','{B6.4}'::text[],false,19),
(E'308ca52a-d772-5219-b2aa-99fb7da4dbbc'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',10,E'The EOC has developed Public Service ContinuityPlan in the event of disaster/disruption.','{B2.7}'::text[],false,20),
(E'b226fd2f-38db-5332-8765-7281d455a610'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',11,E'The EOC has the ability to obtain pre-disaster maps, photographs, and other documents.','{B5.3}'::text[],false,21),
(E'4181e0f5-54de-5987-ba4e-d04612b9fe23'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',12,E'The conditions and process under which the EOC is activated, staffed, and deactivated are defined.','{B1.2,B1.3}'::text[],false,22),
(E'2625b803-2851-5a7a-b6f0-68a7fc0618f2'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',13,E'Warning and Public Information dissemination agreements are in place with local radio, TV, cable TV, newspapers, and other media.','{B3.4}'::text[],false,23),
(E'ffa6b13f-5c0f-58b9-bcd6-f09b5b72572c'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',14,E'The EOC has established alternate methods for contacting media.','{B3.1,B3.4}'::text[],false,24),
(E'b4ed2ff2-3ac5-574f-b00d-8b3da9159eba'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',15,E'Mutual Aid Agreements/Memorandums of Understanding (MOUs)/Twinning Concept/System are in place with other EOCs to obtain trained personnel for augmentation.','{B6.6,B1.5}'::text[],false,25),
(E'88bb7703-e6de-5312-9d06-80bc05452a01'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',16,E'Security measures are addressed in EOC plans and procedures.','{B2.6}'::text[],false,26),
(E'40f839ab-fb51-545d-bfc0-35d35c7d3614'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',17,E'Security plans address actions associated with higher threat levels (e.g., additional barriers, increased surveillance, additional guards).','{B2.6}'::text[],false,27),
(E'11907e72-1b05-5edf-9820-084fed7443b6'::uuid,E'Eoc Assessment and Siting / Capability Assessment / Plans',E'Plans',18,E'Plans address scaled EOC activation and operations depending on the scope of the emergency.','{B1.2,B1.3}'::text[],false,28),
(E'6625b921-d53f-5e79-8f53-4261812f0446'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',1,E'The EOC is in a government owned, privately owned /leased facility.','{}'::text[],true,29),
(E'4ee2cd95-970e-5b82-adab-79173e8204ab'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',2,E'The EOC is in an area that avoids congestion (e.g., transportation chokepoints such as inadequate thoroughfares and bridges) or debris from collapsing buildings.','{B2.1}'::text[],false,30),
(E'bd1e124c-067b-5101-9272-024fdf7510dd'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',3,E'The EOC is located near an adequate road network for ease of access.','{B2.1}'::text[],false,31),
(E'c2e0493f-fe79-57c4-a02c-6597ca3c2805'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',4,E'Government executives/key officials have rapid access to the EOC.','{B2.1}'::text[],false,32),
(E'1816c6e4-7dcc-5241-9129-c64d0fb8b4b3'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',5,E'The EOC has adequateparking for activations.','{B2.4}'::text[],false,33),
(E'ebdf3ef5-ee19-5dc6-aa66-6c08009cac63'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',6,E'The EOC is located outside known high-risk areas (e.g., floods, earthquakes, nuclear power plant, and Hazardous Material (HAZMAT) sites).','{B2.1}'::text[],false,34),
(E'fb24269a-1eb6-51c5-abca-1fe9be85c438'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',7,E'If the EOC is located within a known high-risk area, actions have been taken to mitigate risk.','{B2.1}'::text[],false,35),
(E'2b185c4b-bcf6-5fb8-a874-0a701cc69087'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',8,E'If necessary, the EOC is located away from airfields and airports.','{B2.1}'::text[],false,36),
(E'2c8ebace-cf03-5448-9c3a-116be8844931'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',9,E'The EOC is located away from high-voltage power lines and pipelines.','{B2.1}'::text[],false,37),
(E'514a67e6-380d-541c-a2e8-519ca6e0f2a0'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',10,E'The EOC is situated at a location that allows good radio transmission and reception.','{B3.1,B3.2}'::text[],false,38),
(E'af52cc98-c41a-50b6-a988-94a5c796e532'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',11,E'With respect to seismic safety, the EOC conforms to theNational Building Code of the Philippines (for revision and development).','{B2.2}'::text[],false,39),
(E'bbbef473-fd22-5531-b264-2c7958485b62'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',12,E'The EOC site has a helicopter landing pad/zone or a nearby area clear enough for a helicopter to approach/land.','{}'::text[],true,40),
(E'67a1ab20-16be-50ef-a393-dfa10a567d89'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',13,E'The EOC site can accommodate long-term growth.','{B2.4}'::text[],false,41),
(E'02f1f261-3d2d-554a-bf4c-e96ac850744c'::uuid,E'Eoc Assessment and Siting / Site Selection',E'Site Selection',14,E'Construction of the EOC does not change or alter listed, or nationally-designated, historic sites or structures.','{}'::text[],true,42),
(E'b25b002e-ea4c-5d7f-b39e-e68d243ba26d'::uuid,E'Eoc Assessment and Siting / Site Selection / Mitigation Considerations',E'Mitigation Considerations',1,E'Actions have been taken to mitigate against known relevant risks from natural, accidental, intentional, and human-induced hazards—as identified by jurisdictional hazard and vulnerability assessments.','{B2.1}'::text[],false,43),
(E'5a171e3e-4f3c-59e6-af35-c70c517b05eb'::uuid,E'Eoc Assessment and Siting / Site Selection / Mitigation Considerations',E'Mitigation Considerations',2,E'The EOC has a collective protection system for Chemical, Biological, Radiological, Nuclear, and Explosion(CBRNE) agents.','{}'::text[],true,44),
(E'fb91d862-0182-522a-a411-a1118f2fc40e'::uuid,E'Eoc Assessment and Siting / Site Selection / Mitigation Considerations',E'Mitigation Considerations',3,E'The lowest floor of the EOC is elevated above any flooding and other identified hazards in the jurisdiction’s hazard and vulnerability assessment.','{B2.1}'::text[],false,45),
(E'763d75fe-2d17-5855-b468-42f752badc9a'::uuid,E'Eoc Assessment and Siting / Site Selection / Mitigation Considerations',E'Mitigation Considerations',4,E'EOC is retrofitted to be resilient to seismological hazards','{B2.2}'::text[],false,46),
(E'2fb9e5e5-44fb-5c6d-b8df-50945e84bceb'::uuid,E'Eoc Assessment and Siting / Site Selection / Mitigation Considerations',E'Mitigation Considerations',5,E'The conditions that would cause the EOC to be relocated have been identified.','{B2.7}'::text[],false,47),
(E'70c17b5d-c90d-50b8-829a-3666b03c59e5'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',1,E'The design/construction of the EOCin adherence of the National Building Code is appropriate for the relevant risks identified for the jurisdiction.','{B2.2}'::text[],false,48),
(E'ca9416d0-2d2b-54a0-ada1-f25b51606267'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',2,E'The EOC has the special structural capabilities necessary to improve its survivability/resiliency.','{B2.2}'::text[],false,49),
(E'addff79f-6abc-5eb4-8db2-bc3881b0de84'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',3,E'The EOC has protection from blast effects.','{B2.2}'::text[],false,50),
(E'e8f9a28c-6c74-523c-a907-237f3f23837d'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',4,E'The EOC has built in fire protection and other safety devices (e.g., sprinklers).','{B2.2}'::text[],false,51),
(E'fbc2adcd-9e7c-5f99-ad78-c779e235f8d1'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',5,E'A filtration system to protect personnel from chemical contamination and air-borne pathogenshas been installed for EOCs that are vulnerable to Chemical, Biological, Radiological, Nuclearand Explosive (CBRNE) agentsas indicated by the jurisdiction’s hazard and vulnerability assessment.','{}'::text[],true,52),
(E'8e665ec3-c2e5-5b14-b8ba-83a2c4e47854'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',6,E'Wiring and cabling of the EOC facility is designed to accommodate future expansion.','{B2.4}'::text[],false,53),
(E'1d29ad1a-25bb-50e5-960b-a0386e7c789a'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',7,E'The EOC complies with requirements of Persons with Disabilities(PwD).','{B2.2}'::text[],false,54),
(E'bfd9068d-3da2-578d-a83f-496c24fa6bc1'::uuid,E'Eoc Building Design and Requirements / Building Design',E'Building Design',8,E'EOC design and landscaping blends in with the local community.','{}'::text[],true,55),
(E'8d3ba528-6fa2-5004-ba35-5ec239802592'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',1,E'The building housing the EOC is set back from tree lines.','{B2.6}'::text[],false,56),
(E'4fb8c066-e29d-5574-bb9b-777dc30d0931'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',2,E'Physical security measures (e.g., barriers and gates) are used to restrict vehicle access to the EOC.','{B2.6}'::text[],false,57),
(E'4c35d645-92d0-5a03-9bd4-50f122be934d'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',3,E'The EOC is located in an area where it can quickly be secured.','{B2.6}'::text[],false,58),
(E'cebbd341-8822-538f-92b3-533c3a62541a'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',4,E'Access to the EOC is controlled by a badge, card-swipe, and/or biometric system. The security system in use is adequate to control access to the facility and within the facility.','{B2.6}'::text[],false,59),
(E'31d73f11-28f9-51e8-8274-24d0e1a3ec33'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',5,E'There are no access control systems (i.e., card access, elevators, or lockout stairwells) that could preclude access to or egress from the facility if rendered non-operational.','{B2.6}'::text[],false,60),
(E'cbfd6e9d-4d8e-5f17-837b-376f5a79d781'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',6,E'If the building shares access with another organization, processes are in place to restrict access to operational areas when appropriate.','{B2.6}'::text[],false,61),
(E'721d5798-435a-5712-b9bf-8be2fa495303'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',7,E'Consideration of security measures and implementation to secure parking areas.','{B2.6}'::text[],false,62),
(E'ea8ac6dd-0f6d-5ff7-9b1c-19b817fed69d'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',8,E'Consideration, if appropriate, to provide Closed Circuit Television (CCTV) monitoring at all angles in case of possible security breach.','{B2.6,B3.6}'::text[],false,63),
(E'2589c9a3-4b70-5cf8-8237-050ac7fac0fb'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',9,E'Adequate lighting is provided both inside and outside the EOC.','{B2.6}'::text[],false,64),
(E'18742420-5a27-5975-86b6-8f090195dc57'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',10,E'Appropriate security measures have been considered and taken to ensure safety of items received.','{B2.6}'::text[],false,65),
(E'1dea632d-5440-5c12-ae3a-9e41d2c24221'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',11,E'Consideration of security measures and implementationto control access to the facility.','{B2.6}'::text[],false,66),
(E'14516128-d789-5bf2-a6b8-dae9cc54e7c2'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',12,E'Access is restricted to control panels of critical systems.','{B2.6}'::text[],false,67),
(E'ae249ba2-4124-5e12-af21-3fb6b1f98e44'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',13,E'Ventilation, and air-conditioning (VAC) systems are available and controllable 24-hours a day, seven days a week.','{B2.4}'::text[],false,68),
(E'1391a945-dcaf-58cc-9fa5-f44a81fdd8c6'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',14,E'Appropriate/authorized staff has 24-hour access to the facility.','{B2.6}'::text[],false,69),
(E'c2e9be75-84f1-5a82-b13e-85ebbaf69f7e'::uuid,E'Eoc Building Design and Requirements / Building Design / Physical Security',E'Physical Security',15,E'Periodic inspection of all personnel, equipment, and systems.','{B7.6}'::text[],false,70),
(E'3176c1a7-05fe-5865-a73d-7796d6de807c'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',1,E'If EOC space is not dedicated, plans are in place to relocate day staff to another location to ensure efficiency of emergency functions.','{B2.4}'::text[],false,71),
(E'e6e53a24-2a52-5740-bbd9-78d74e243bbe'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',2,E'The EOC and any multi-use space have the capability to display audio-visual media.','{B3.6,B2.4}'::text[],false,72),
(E'9ef34f88-b415-5916-a7eb-76bd329a1562'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',3,E'The EOC and any multi-use space have the capability to receive public,via intercom, announcements.','{B2.4}'::text[],false,73),
(E'7487ff45-fc5e-5350-9840-e036b5961a88'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',4,E'The communication system within the EOC is located next to the operating room.','{B2.4}'::text[],false,74),
(E'90840a98-e673-5518-b83c-c92874b020ff'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',5,E'The EOC has space, whether in one large room or a complex of rooms, for an operations area to perform emergency response and management functions;a communications room for centralized facsimiles, radios, and video teleconferencing (VTC); and to secure communications (e.g., secure voice, facsimile, and VTC).','{B2.4}'::text[],false,75),
(E'27cf885a-3b8b-5056-85b7-86d17d6451c8'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',6,E'The EOC has a dedicated communications room/center. This room/center is adequate to support EOC communications requirements.','{B2.4}'::text[],false,76),
(E'571c71f0-5c0e-5d2a-8c27-3cd2a3af103e'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',7,E'The EOC has access to support areas(e.g., file room and server sites).','{B2.4}'::text[],false,77),
(E'38acee17-af71-54d5-9f66-e851af292ab8'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',8,E'Once activated, the EOC has a dedicated operations room with adequate space to support the emergency response and EOC staff.','{B2.4}'::text[],false,78),
(E'bff3772c-d348-5b38-ab24-2c5787edeffe'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',9,E'The EOC has adequate facilities for food storage/preparation.','{B2.4,B2.5}'::text[],false,79),
(E'7d7688d1-cbf1-5f91-937c-5e6ea006ab3d'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',10,E'The EOC has an uninterruptible power supply (UPS) to critical systems. The duration of the UPS is adequate to support these systems/functions until the backup power comes on line.','{B2.3}'::text[],false,80),
(E'dca53bb7-5c7a-5fa2-b50c-0033e4aaee5b'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',11,E'The EOC has a system to ensure backup power and emergency power generation.','{B2.3}'::text[],false,81),
(E'8e5ba464-4833-549b-b13b-6d02ea1a70de'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',12,E'The EOC has auxiliary lighting (e.g., flashlights, lanterns, batteries, and bulbs).','{B2.3}'::text[],false,82),
(E'6284f7d9-38a0-5e7c-b13f-da2114461e4c'::uuid,E'Eoc Building Design and Requirements / Room Design',E'Room Design',13,E'There is a dedicated auditorium-type/conference/media/break-out room/s in the general vicinity of the EOC. This room can be closed off to prevent an impact on operational activity.','{B2.4}'::text[],false,83),
(E'2f24349d-70b7-57eb-8085-264e57dc4701'::uuid,E'Eoc Building Design and Requirements / Personnel Space Requirements',E'Personnel Space Requirements',1,E'In accordance with the prescribed FEMA standards, the EOC allocates 150–200sq. ft. per person for the number of EOC staff assigned in an emergency.','{B2.4}'::text[],false,84),
(E'630250c4-9812-53d2-8ff7-2ef98fc59ab1'::uuid,E'Eoc Building Design and Requirements / Personnel Space Requirements',E'Personnel Space Requirements',2,E'Additional personnel space requirements are based upon maximum staffing levels for sustained operations (i.e., minimum – 72 hours: restrooms, meeting spaces, quiet rooms, executive office space, recreational room, fitness room, and smoking areas).','{B2.4,B4.3}'::text[],false,85),
(E'81438448-d0e1-5dbe-9a26-86f976e4c52e'::uuid,E'Eoc Building Design and Requirements / Personnel Space Requirements',E'Personnel Space Requirements',3,E'EOC design takes into account personnel space needs during sustained operations (i.e., minimum – 72 hours: showers and condensed bedding options).','{B2.4,B2.5}'::text[],false,86),
(E'dfcd3730-f515-588d-b577-ed63048fcd07'::uuid,E'Eoc Building Design and Requirements / Personnel Space Requirements',E'Personnel Space Requirements',4,E'The EOC could provide sleeping accommodations to support sustained operations, if necessary (i.e., minimum – 72 hours).','{B2.4,B2.5}'::text[],false,87),
(E'80cb208d-ae1f-53bb-9368-ce8d7621b3c8'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',1,E'Local Area Networks (LAN) and State-Wide Area Networks (WAN) supporting emergency operations have adequate protection against cyber-attack (e.g., unauthorized access, denial of service, or malicious code).','{B3.5}'::text[],false,88),
(E'30470eb9-f5bc-5ae5-836c-d708db69b865'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',2,E'Written procedures and guidelines exist for data/information handling.','{B3.5}'::text[],false,89),
(E'6328fb7e-48b0-5c40-8925-cf2107b77579'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',3,E'Adequate processes and access-control procedures are in place to protect secure communications areas.','{B3.5,B2.6}'::text[],false,90),
(E'e2b323ee-5864-590c-afe8-079bfa3249c1'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',4,E'Areas where classified or sensitive information is discussed can be isolated from unauthorized/un-cleared individuals.','{B3.5}'::text[],false,91),
(E'89f29ed7-524c-5cb5-a136-195d9fc6fc13'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',5,E'The EOC has an uninterruptible power supply (UPS) to critical systems (e.g. servers). The duration of the UPS is adequate to support these systems/functions until the backup power comes on line.','{B2.3}'::text[],false,92),
(E'e101898b-38e6-5ccc-b74f-7da5ba61675a'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',6,E'Radio communications are protected (i.e., encrypted or have privacy features).','{B3.5}'::text[],false,93),
(E'bded8d34-d2f5-5a2f-807f-7a4b78079f29'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',7,E'The EOC has a secure facsimile capability.','{B3.5}'::text[],false,94),
(E'd027ae50-65bb-5515-8597-7a53043c834c'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',8,E'The EOC has a secure communications room with space adequate to support cleared EOC staff and secure communications requirements.','{B3.5,B2.4}'::text[],false,95),
(E'e79a71be-96b9-518a-b372-7e6c7b9d9a69'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',9,E'The EOC has secure communication capabilities and procedures with law enforcement and other consequence management agencies (e.g., WMD terrorism response).','{B3.5,B3.4}'::text[],false,96),
(E'785081a2-bcef-538f-bbd9-063d216045e7'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',10,E'The EOC has conducted a communications, electronics and information systems assessment to identify information security weaknesses. Corrective actions have been implemented.','{B3.5,B7.6}'::text[],false,97),
(E'915f6bbb-2188-5e19-8df5-28bfb7ed3111'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',11,E'Awareness training has ensured that EOC computer users understand the security risks associated with networked computers and practice good security.','{B3.5,B7.2}'::text[],false,98),
(E'c3d44b8d-8c07-5982-8cb1-9afcda4d96dc'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',12,E'Clear and consistent information concerning information security policies and procedures are given to EOC staff.','{B3.5}'::text[],false,99),
(E'361ec0a0-7c58-5bd2-a455-71a78ea8d86d'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',13,E'EOC automation systems are protected by technical solutions such as firewalls and smartcards. Virus updates occur regularly.','{B3.5}'::text[],false,100),
(E'3f48f4aa-f55e-540b-b576-dc73b672b2f7'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',14,E'If personnel with security clearances are required, there are at least five with clearances who are trained to use secure equipment, control and protect classified material, and manage and control communications security.','{B3.5,B4.2}'::text[],false,101),
(E'01a5484d-f8df-5f54-8120-91258ec48023'::uuid,E'Communications and Information Management / Information Management Systems',E'Information Management Systems',15,E'The EOC has the capability to assimilate hazard information into a common format, such as a digital Geographic Information System (GIS), for comparative evaluation.','{B5.3}'::text[],false,102),
(E'4922e9ce-065c-58f9-8a3d-baf21ce18bd3'::uuid,E'Eoc Management and Standard Operating Procedures / Standard Operating Procedures',E'Standard Operating Procedures',1,E'Emergency public informationprocedures','{B7.1}'::text[],false,103),
