(E'c25b5a8a-7cda-567d-a4de-abe77884f955'::uuid,E'Eoc Management and Standard Operating Procedures / Standard Operating Procedures',E'Standard Operating Procedures',3,E'Security procedures','{B2.6}'::text[],false,105),
