(E'659ef7f3-cd0b-50cc-9aab-0e08115f2d34'::uuid,E'Eoc Management and Standard Operating Procedures / Standard Operating Procedures',E'Standard Operating Procedures',11,E'Procedures for after action reporting','{B7.4}'::text[],false,113),
(E'b1fa739d-0f90-5e2a-933a-7451ecdb8217'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Communications',E'Communications',1,E'The EOC has an alternate communication system.','{B3.1}'::text[],false,114),
(E'090ac062-d1e3-5b85-9d98-0abd65c00ee3'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Communications',E'Communications',2,E'The EOC has separate, dedicated facsimiles to transmit and receive documents.','{B3.1}'::text[],false,115),
(E'72fb11d0-1f20-5af0-8c91-36e53872258f'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Communications',E'Communications',3,E'Mobile or transportable telecommunication systems are identified, coordinated, and tested.','{B3.1,B3.3}'::text[],false,116),
(E'047177e6-c236-5910-897c-cb8d082d2c08'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Communications',E'Communications',4,E'Alternate communication systems are identified for use in an emergency.','{B3.1}'::text[],false,117),
