(E'd61c7ae1-d831-5a3f-a003-83de457a556d'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',2,E'The EOC has an adequate supply of fuel for sustained operations (i.e., minimum—72 hours).','{B2.3}'::text[],false,120),
