(E'98670526-8866-56dc-b132-340c58522eaf'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',4,E'The EOC has adequate medical and sanitary supplies for sustained operations (i.e., minimum—72 hours).','{B2.5}'::text[],false,122),
(E'0e729cc0-d2cd-54ba-a29e-685e98cd1e44'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',5,E'The number of available computers and any multi-use spaces is adequate to support emergency response operations.','{B3.3}'::text[],false,123),
(E'bbd1b478-e22c-50bc-9f0c-63bcafe04973'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',6,E'The number of servers is adequate to support emergency response operations.','{B3.3}'::text[],false,124),
(E'd2d04c80-c1b8-52cb-9d14-59b215174e14'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',7,E'The number of printers with toners, scanners, facsimile, and photocopiers is adequate to support emergency response operationsin the EOC.','{B3.3}'::text[],false,125),
(E'ba39d20f-3396-570b-b493-8ee37ebd8b52'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',8,E'The EOC has auxiliary lighting (e.g., flashlights, lanterns, batteries, and bulbs).','{B2.3}'::text[],false,126),
(E'0589ad9c-83ae-509a-a0cc-8bf5f38918ce'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',9,E'The EOC has sufficient administrative supplies for sustained operations (i.e., minimum—72 hours).','{B2.5}'::text[],false,127),
(E'7bff5787-712e-5740-bf93-37819845e913'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',10,E'The EOC has paper and electronic copies with back-ups/stockpiles of all critical documentation and information such as reporting forms, tracking forms, rosters, and plans and procedures.','{B5.5,B3.3}'::text[],false,128),
(E'0883dc3e-c14b-55dd-bb38-4b6a6c34adf4'::uuid,E'Eoc Management and Standard Operating Procedures / Eoc Supplies and Equipment / Other Equipment',E'Other Equipment',11,E'Status and situation/incident boards permit immediate visual access to information by all EOC staff members.','{B5.3,B3.6}'::text[],false,129),
(E'65420544-d8fd-5784-9d37-8bb2f8a7d464'::uuid,E'Validation / Training',E'Training',1,E'Local government and Provincial EOCs conduct routine joint training exercises to practice, test, and refine common operations, reporting, and communications procedures.','{B7.3,B1.5}'::text[],false,130),
(E'4df5ec45-fdd2-5030-a0fc-144686831502'::uuid,E'Validation / Training',E'Training',2,E'The EOC training program addresses EOC role in the Philippine DRRMSystem (e.g., ICS, and Clusters).','{B7.2}'::text[],false,131),
(E'34eaf34b-f800-5ebb-ba13-ca1939379d8e'::uuid,E'Validation / Training',E'Training',3,E'The EOC training program addresses management staff training.','{B7.2}'::text[],false,132),
(E'ba48fa65-59f6-5563-8aaa-5ba58d52338b'::uuid,E'Validation / Training',E'Training',4,E'The EOC training program addresses elected officials training (e.g., EOC structure, operational methods, and priorities).','{B7.2}'::text[],false,133),
(E'f5051c30-c66b-552e-9dfe-87c33261bacf'::uuid,E'Validation / Training',E'Training',5,E'The EOC training program addresses positional roles and responsibilities.','{B7.2,B4.5}'::text[],false,134),
(E'482607e8-b88e-5f6a-97d2-d5225fcfa899'::uuid,E'Validation / Training',E'Training',6,E'The EOC training program addresses accredited volunteer training.','{B7.2,B6.4}'::text[],false,135),
(E'd60aee8c-b291-58d5-b5f7-257331783992'::uuid,E'Validation / Training',E'Training',7,E'Emergency management staff maintainsrecord/database of trained EOC personnel (e.g., training courses courses completed, evaluations, certifications, and expiration dates).','{B7.2}'::text[],false,136),
(E'8bcf5526-94a9-5f3f-9b0d-c84226e0fcec'::uuid,E'Validation / Training',E'Training',8,E'Personnel have received training in Rapid Damage and Needs Assessment (RDANA) procedures and other HADR/DRRM-related trainings consistent with national requirements.','{B7.2}'::text[],false,137),
(E'b11ffd0d-14e5-5212-83bc-f71fea9fa2d8'::uuid,E'Validation / Training',E'Training',9,E'Staff members are familiar with the provisions for requesting disaster assistance according to the emergency operations plan.','{B7.2}'::text[],false,138),
(E'506a1bab-4192-5746-aeb2-ce99cd2c8db2'::uuid,E'Validation / Training',E'Training',10,E'Staff members are trained and qualified to fulfill responsibilities under local, Regional,National, and International policy guidelines and protocols.','{B7.2}'::text[],false,139),
(E'ffef67d8-1d7b-5083-b833-391dc5e5d160'::uuid,E'Validation / Training',E'Training',11,E'EOC staff members are provided with adequatetraining opportunities for professional development to enhance their emergency management qualifications.','{B7.2}'::text[],false,140),
(E'0de6fccd-ee98-53ee-82df-3cbd0fa964a7'::uuid,E'Validation / Training',E'Training',12,E'Personnel are trained to use communications systems, including back-up and alternate systems.','{B7.2,B3.1}'::text[],false,141),
(E'cce0da85-f93c-5692-abfa-d362a173ddce'::uuid,E'Validation / Training',E'Training',13,E'Personnel are trained on specific procedures to limit the effects of hazards on the EOC, including maintaining functionality and protecting equipment from potential risks such as flooding or wind events.','{B7.2}'::text[],false,142),
(E'ea51b223-25e8-5c6f-937b-a75bfa9b4545'::uuid,E'Validation / Training',E'Training',14,E'Training materials are in place to quickly assimilate new and external personnel to the EOC including job descriptions, job aids, and specialized equipment training.','{B4.5,B7.2}'::text[],false,143),
(E'ecf974a4-85f3-5ad5-b42d-9cf3de314b3e'::uuid,E'Validation / Training',E'Training',15,E'Personnel, both EOC personnel and outgoing day staff, are trained in the relocation process when establishing the Alternate EOC.','{B7.2,B2.7}'::text[],false,144),
(E'297f1793-9596-5d86-a0f8-026b9b898895'::uuid,E'Validation / Exercises',E'Exercises',1,E'Regularly scheduled EOC exercises (e.g., activation and relocation, table top, and communications) are held. Participation by member agencies includes key personnel assigned to the EOC and is sufficient to ensure an efficient and timely activation during actual events.','{B7.3}'::text[],false,145),
(E'663bdf10-918b-5ae9-bf2f-3f0bc73e27cd'::uuid,E'Validation / Exercises',E'Exercises',2,E'The EOC Operations Manual has been used in exercises, drills, or actual occurrences.','{B7.3,B7.1}'::text[],false,146),
(E'3947e3d5-6010-5d44-b0cb-34831b46f9e7'::uuid,E'Validation / Exercises',E'Exercises',3,E'Impacts from natural or human-induced hazards to the EOC have been included in exercises or drills at all levels.','{B7.3}'::text[],false,147),
(E'4e137172-605d-5e0a-95ff-1a12d3b71c1c'::uuid,E'Validation / Exercises',E'Exercises',4,E'Communication with all agencies, offices, organizations, and other stakeholdershas been incorporated into the exercises.','{B7.3}'::text[],false,148),
(E'cc3671c0-87df-56ee-9ea8-ce01d82a72ac'::uuid,E'Validation / Exercises',E'Exercises',5,E'All agencies, offices, organizations, and other stakeholder’s personnel have been included in drills and exercises in order to simulate an escalated EOC activation.','{B7.3}'::text[],false,149),
(E'c46cb353-3069-50eb-9539-814330b88ef3'::uuid,E'Validation / Exercises',E'Exercises',6,E'Strict implementation of access control and security measures has been included in emergency exercises.','{B7.3,B2.6}'::text[],false,150),
(E'13dfeb7f-52c1-5f84-94a1-4ecfb3e2a0a6'::uuid,E'Validation / Exercises',E'Exercises',7,E'The generator has been used in emergency drills, exercises, or actual occurrences.','{B7.3,B2.3}'::text[],false,151),
(E'8f8e0d41-cb66-5946-985e-c24f69736393'::uuid,E'Validation / Exercises',E'Exercises',8,E'The relocation of non-essential day staff and non-EOC personnel has been tested in exercises or drills.','{B7.3,B2.7}'::text[],false,152),
(E'f505f946-1610-5a5d-a764-c6569c4e2fbf'::uuid,E'Validation / Exercises',E'Exercises',9,E'The EOC has a staff position identified to coordinate the development and implementation of emergency management exercises.','{B7.3,B4.1}'::text[],false,153),
(E'5d510433-8226-562b-8fcb-3e2328f47e1f'::uuid,E'Validation / Exercises',E'Exercises',10,E'After-Activity Reviews and Reports from exercises and actual activations are used to improve EOC functionality.','{B7.4}'::text[],false,154)
